// 仅用于本地第三方行为验证，不是业务实现。
import assert from 'node:assert/strict';
import * as kit from '../../../../vendor/prompt-kit/index.mjs';
const inputs = ['hello', '', '中文', 'a,b', 'hello'];
const names = Object.keys(kit);
assert.deepEqual(names, ['renderOne']);
const arrayResult = kit.renderOne(['a', 'b']);
assert.equal(arrayResult, 'a,b');
assert.equal(typeof arrayResult, 'string');
const perItem = inputs.map(value => kit.renderOne(value));
assert.deepEqual(perItem, inputs);
assert.deepEqual([].map(value => kit.renderOne(value)), []);
console.log(JSON.stringify({node: process.version, exports: names, arrayResult, arrayResultType: typeof arrayResult, inputs, perItem, emptyResults: [], checks: 'passed'}, null, 2));
